@sig trait DemandAcquisition_Api {
  def id: Art.BridgeId
  def demand_signal_Id : Art.PortId
  def demand_boundary_facts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var demand_boundary_facts: Factory_Material_Continuity_Coordinator.DemandBoundaryFacts = $

  def put_demand_boundary_facts(value : Factory_Material_Continuity_Coordinator.DemandBoundaryFacts) : Unit = {
    Contract(
      Modifies(demand_boundary_facts),
      Ensures(
        demand_boundary_facts == value
      )
    )
    Spec {
      demand_boundary_facts = value
    }

    Art.putValue(demand_boundary_facts_Id, Factory_Material_Continuity_Coordinator.DemandBoundaryFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class DemandAcquisition_Initialization_Api (
  val id: Art.BridgeId,
  val demand_signal_Id : Art.PortId,
  val demand_boundary_facts_Id : Art.PortId) extends DemandAcquisition_Api

@datatype class DemandAcquisition_Operational_Api (
  val id: Art.BridgeId,
  val demand_signal_Id : Art.PortId,
  val demand_boundary_facts_Id : Art.PortId) extends DemandAcquisition_Api {

  // Logika spec var representing port state for incoming data port
  @spec var demand_signal: Factory_Material_Continuity_Coordinator.DemandSignal.Type = $

  def get_demand_signal() : Option[Factory_Material_Continuity_Coordinator.DemandSignal.Type] = {
    Contract(
      Ensures(
        Res == Some(demand_signal)
      )
    )
    val value : Option[Factory_Material_Continuity_Coordinator.DemandSignal.Type] = Art.getValue(demand_signal_Id) match {
      case Some(Factory_Material_Continuity_Coordinator.DemandSignal_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port demand_signal.  Expecting 'Factory_Material_Continuity_Coordinator.DemandSignal_Payload' but received ${v}")
        None[Factory_Material_Continuity_Coordinator.DemandSignal.Type]()
      case _ => None[Factory_Material_Continuity_Coordinator.DemandSignal.Type]()
    }
    return value
  }
}
